plist.dict:

LSUIElement

    CFBundlePackageType
    APPL
    CFBundleName
    {{.Info.ProductName}}
    CFBundleExecutable
    {{.OutputFilename}}
    CFBundleIdentifier
    com.wails.{{safeBundleID .Name}}
    CFBundleVersion
    {{.Info.ProductVersion}}
    CFBundleGetInfoString
    {{.Info.Comments}}
    CFBundleShortVersionString
    {{.Info.ProductVersion}}
    CFBundleIconFile
    iconfile
    LSMinimumSystemVersion
    10.13.0
    NSHighResolutionCapable
    true
    NSHumanReadableCopyright
    {{.Info.Copyright}}
    {{if .Info.FileAssociations}}
    CFBundleDocumentTypes

      {{range .Info.FileAssociations}}

        CFBundleTypeExtensions

          {{.Ext}}

        CFBundleTypeName
        {{.Name}}
        CFBundleTypeRole
        {{.Role}}
        CFBundleTypeIconFile
        {{.IconName}}

      {{end}}

    {{end}}
    {{if .Info.Protocols}}
    CFBundleURLTypes

      {{range .Info.Protocols}}

            CFBundleURLName
            com.wails.{{.Scheme}}
            CFBundleURLSchemes

                {{.Scheme}}

            CFBundleTypeRole
            {{.Role}}

      {{end}}

    {{end}}
